<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $base = App\Core\Config::url('/campeonatos/' . $championship['slug']); $labels = ['referee' => 'Árbitro', 'assistant' => 'Assistente', 'fourth_official' => 'Quarto oficial', 'scorekeeper' => 'Mesário', 'coordinator' => 'Coordenador']; $initials = static function (string $value): string { $parts = preg_split('/\s+/', trim($value)) ?: []; return strtoupper(substr($parts[0] ?? 'A', 0, 1) . substr($parts[1] ?? '', 0, 1)); }; ?>
<section class="portal-page-heading"><p class="eyebrow"><?= $e($championship['name']) ?></p><h1>Arbitragem</h1><p>Conheça os árbitros e oficiais cadastrados para esta competição.</p></section>
<section class="official-grid"><?php foreach ($officials as $official): ?><article class="official-card"><?php if ($official['photo_path']): ?><img src="<?= $e($base . '/arbitragem/' . $official['id'] . '/foto') ?>" alt="Foto de <?= $e($official['public_name'] ?: $official['full_name']) ?>"><?php else: ?><span class="official-avatar"><?= $e($initials((string) ($official['public_name'] ?: $official['full_name']))) ?></span><?php endif; ?><div><p class="eyebrow"><?= $e($labels[$official['role']] ?? $official['role']) ?></p><h2><?= $e($official['public_name'] ?: $official['full_name']) ?></h2></div></article><?php endforeach; ?><?php if (!$officials): ?><div class="empty-state"><strong>Relação de arbitragem em atualização.</strong><p>Os oficiais aparecerão aqui quando forem publicados pela organização.</p></div><?php endif; ?></section>
